def design(p):
 for id,desc,css in [
 ('cutout-portrait','紙の切抜きのような輪郭と、横に添えた短い署名で人物を示す。','${--sg-a:#cab795;--sg-muted:#b9aa90;--sg-line:#9d8666}$ .sg-avatar-list{gap:16px}$ .sg-person{gap:9px;padding:8px 5px 12px;border-bottom:2px solid #957855;max-width:90px}$ .sg-portrait{width:74px;height:88px;transform:rotate(-3deg)}$ .sg-portrait-picture{inset:0;border-radius:0;clip-path:polygon(6% 0,100% 3%,97% 95%,84% 100%,3% 96%,0 5%);background:linear-gradient(145deg,#b3b793,#566c61);border:4px solid #e0cfa8}$ .sg-portrait-ring{display:none}$ .sg-person[data-selected=true]{border-bottom-color:#e4cba1}$ .sg-person[data-selected=true] .sg-portrait{transform:rotate(2deg)}$ .sg-person-name{font:italic 13px Georgia}'),
 ('lattice-portrait','角い写真を細い格子の後ろへ置き、選択した人物の枠を開く。','${--sg-a:#a8cdd5;--sg-line:#6f99a6;--sg-muted:#9ebbc3}$ .sg-avatar-list{gap:18px}$ .sg-portrait{width:77px;height:77px}$ .sg-portrait-picture{inset:8px;border-radius:2px;background:linear-gradient(145deg,#acc6c5,#476b86)}$ .sg-portrait-ring{inset:0;border-radius:0;border:1px solid #93b2b9;transform:rotate(3deg);box-shadow:inset 0 0 0 3px #172e33}$ .sg-portrait-ring:after{content:"";position:absolute;inset:6px;border:1px solid #b7d3cd;border-left:0;border-right:0;transform:rotate(-6deg)}$ .sg-person[data-selected=true] .sg-portrait-ring{transform:rotate(-5deg);border-width:3px}$ .sg-person-copy{border-left:1px solid #79a1af;padding-left:8px;text-align:left}'),
 ('keyhole-portrait','丸い上辺と細い下辺を持つ人物窓が、短い名札へ続く。','${--sg-a:#b8c5df;--sg-line:#7f8ead;--sg-muted:#a6b3cf}$ .sg-portrait{width:73px;height:91px}$ .sg-portrait-picture{inset:3px;border-radius:45% 45% 12px 12px;background:radial-gradient(at 30% 15%,#b4c4d9,#344966)}$ .sg-portrait-ring{border-radius:48% 48% 15px 15px;border:2px solid #8d9db4;box-shadow:0 4px 0 #172a3b88}$ .sg-person-copy{background:#304359;border:1px solid #758eaa;padding:7px 10px;border-radius:2px;width:100%}$ .sg-person[data-selected=true] .sg-person-copy{background:#576f8e;border-color:#c4d0dd}'),
 ('postmark-portrait','消印のような外周と短い水平線が、人物の識別印を作る。','${--sg-a:#c3cfa9;--sg-line:#8f9e73;--sg-muted:#abb791}$ .sg-portrait{width:81px;height:81px}$ .sg-portrait-picture{inset:10px;border-radius:50%;background:radial-gradient(at 25% 15%,#d0d5ac,#47694c)}$ .sg-portrait-ring{border:3px dotted #9dac7c;border-radius:50%;transform:rotate(-10deg)}$ .sg-portrait-ring:after{content:"";position:absolute;left:70%;right:-23px;top:28px;height:7px;border-top:1px solid #9bab7b;border-bottom:1px solid #9bab7b}$ .sg-person[data-selected=true] .sg-portrait-ring{border-color:#d3dfac;transform:rotate(12deg)}$ .sg-person-name{font:13px Georgia;text-decoration:underline;text-underline-offset:5px}'),
 ('dossier-identity','広い人物行に、写真・名前・在席の印を資料のように揃える。','${--sg-a:#d0b6ca;--sg-line:#a083a0;--sg-muted:#bba5bc}$ .sg-avatar-list{display:grid;gap:9px}$ .sg-person{max-width:none;width:100%;flex-direction:row;gap:17px;text-align:left;background:#3e2e49;border-left:7px solid #806186;padding:10px 15px}$ .sg-portrait{width:45px;height:54px}$ .sg-portrait-picture{inset:1px;border-radius:1px;background:linear-gradient(145deg,#ae8fbd,#44385e)}$ .sg-portrait-ring{display:none}$ .sg-person-copy{border-top:1px solid #a287b166;padding-top:7px;align-items:flex-start;flex:1}$ .sg-person[data-selected=true]{background:#675072;border-left-color:#dabce0}$ .sg-person-name{letter-spacing:1px;font:14px Georgia}'),
 ('bookend-portrait','人物の写真を二つの厚い支柱で支え、名前を下の細い空間へ置く。','${--sg-a:#cbb9a3;--sg-line:#a18b6f;--sg-muted:#b8a98f}$ .sg-portrait{width:74px;height:77px}$ .sg-portrait-picture{inset:5px 10px;border-radius:0;background:linear-gradient(120deg,#b8bd9e,#4e665f)}$ .sg-portrait-ring{border-top:0;border-bottom:0;border-left:5px solid #9b8567;border-right:5px solid #9b8567;border-radius:0;box-shadow:2px 4px #242b2577}$ .sg-person-copy{border-top:1px solid #9f8e7355;padding-top:9px}$ .sg-person[data-selected=true] .sg-portrait-ring{border-left-color:#e0c49b;border-right-color:#e0c49b;transform:scaleX(1.08)}'),
 ('staggered-portrait','写真と署名の高さを交互にずらし、人物の列に穏やかなリズムを作る。','${--sg-a:#b9d5d1;--sg-line:#82a7ae;--sg-muted:#a7bdc4}$ .sg-avatar-list{gap:14px;align-items:center}$ .sg-person{max-width:88px;padding:10px 0;border-left:1px solid #769ba7;gap:11px}$ .sg-person:nth-child(even){flex-direction:column-reverse;transform:translateY(11px)}$ .sg-portrait{width:70px;height:70px}$ .sg-portrait-picture{inset:3px;border-radius:10px 2px 10px 2px;background:radial-gradient(at 15% 15%,#abc9d0,#42687d)}$ .sg-portrait-ring{border-radius:12px 3px 12px 3px;border:1px solid #80a7ad}$ .sg-person[data-selected=true]{border-left:4px solid #b9d8cc;padding-left:3px}'),
 ('edge-light-portrait','暗い写真窓の一辺を光らせ、名前を光の延長として揃える。','${--sg-a:#bed2dc;--sg-line:#8099aa;--sg-muted:#a6bbc7}$ .sg-portrait{width:75px;height:85px}$ .sg-portrait-picture{inset:0 5px 0 3px;border-radius:1px;background:linear-gradient(130deg,#738f9b,#152e49);border-right:4px solid #6e9eac}$ .sg-portrait-ring{border:0;border-left:1px solid #8bb0bf;border-radius:0;transform:translateX(-4px)}$ .sg-person-copy{padding-left:11px;border-left:1px solid #7f9bb0;align-items:flex-start;text-align:left}$ .sg-person[data-selected=true] .sg-portrait-picture{border-right-color:#c3e0dc;box-shadow:5px 0 16px #9ad1d933}$ .sg-person-name{font-weight:400;letter-spacing:.5px}'),
 ('medallion-sash-profile','縦長の人物印と、下に折り返した名前の帯を一つにする。','${--sg-a:#dec3a7;--sg-line:#a28b6b;--sg-muted:#baa78d}$ .sg-portrait{width:71px;height:91px}$ .sg-portrait-picture{inset:4px;border-radius:35% 35% 50% 50%;background:radial-gradient(at 25% 20%,#d4c9ac,#506c64);border:2px solid #b69b70}$ .sg-portrait-ring{border:1px solid #b8a078;border-radius:37% 37% 52% 52%;box-shadow:0 6px #313c2f55}$ .sg-person-copy{background:#7a6046;padding:7px 10px;clip-path:polygon(0 0,100% 0,92% 100%,8% 100%);color:#f0dfbb}$ .sg-person-sub{color:#d6c4a5}$ .sg-person[data-selected=true] .sg-person-copy{background:#a4825c}'),
 ('aperture-ticket-profile','写真の脇の小さな切欠きと、横向きの署名が個人を区別する。','${--sg-a:#c6b9d7;--sg-line:#9685ab;--sg-muted:#b7aacd}$ .sg-avatar-list{gap:15px}$ .sg-person{max-width:95px;flex-direction:row;gap:6px;align-items:center}$ .sg-portrait{width:53px;height:92px}$ .sg-portrait-picture{inset:3px;border-radius:3px;background:linear-gradient(135deg,#b7a8cd,#564676);clip-path:polygon(0 0,100% 0,100% 38%,87% 44%,100% 50%,100% 100%,0 100%)}$ .sg-portrait-ring{border:1px solid #b39cc7;border-radius:3px}$ .sg-person-copy{writing-mode:vertical-rl;max-height:118px;padding:4px 2px;border-top:2px solid #876c9f;align-items:center}$ .sg-person-sub{display:none}$ .sg-person[data-selected=true] .sg-person-copy{border-top-color:#e1c5ee}'),
 ('crossmount-profile','四つの小さな角台で写真を留め、選択時に角の間隔を広げる。','${--sg-a:#b9d4c2;--sg-line:#83a18b;--sg-muted:#abc1ae}$ .sg-portrait{width:80px;height:80px}$ .sg-portrait-picture{inset:10px;border-radius:3px;background:linear-gradient(145deg,#bacfa7,#45684c)}$ .sg-portrait-ring{border:4px solid #8ba37b;border-radius:0;clip-path:polygon(0 0,23% 0,23% 7%,7% 7%,7% 23%,0 23%,0 0,100% 0,100% 23%,93% 23%,93% 7%,77% 7%,77% 0,100% 0,100% 100%,77% 100%,77% 93%,93% 93%,93% 77%,100% 77%,100% 100%,0 100%,0 77%,7% 77%,7% 93%,23% 93%,23% 100%,0 100%)}$ .sg-person[data-selected=true] .sg-portrait-ring{transform:scale(1.08);border-color:#c5d9ac}$ .sg-person-name{font:13px Georgia;letter-spacing:.3px}'),
 ('frontispiece-profile','大きな上の写真窓と、見出しのような署名を二段に組む。','${--sg-a:#ccbad1;--sg-line:#957f9d;--sg-muted:#b9a7c0}$ .sg-avatar-list{gap:11px}$ .sg-person{max-width:91px;border-top:3px solid #9676a0;padding:9px 0 0;gap:11px}$ .sg-portrait{width:83px;height:106px}$ .sg-portrait-picture{inset:0;border-radius:1px;background:linear-gradient(145deg,#a393b7,#483d6d);border-bottom:8px solid #6e577c}$ .sg-portrait-ring{display:none}$ .sg-person-name{font:15px/1.25 Georgia;letter-spacing:-.3px}$ .sg-person-sub{font-size:8px;padding-top:4px;border-top:1px solid #9d84aa66}$ .sg-person[data-selected=true]{border-top-color:#d8bde0}$ .sg-person[data-selected=true] .sg-portrait-picture{border-bottom-color:#b993c0}'),
 ]:p('avatars',id,desc,css)
 # These rating forms use native radios; shape is independently authored per rank surface.
 ratingbase='$ .sg-rating-star{display:none}$ .sg-rating-form{inset:2px 0 17px}$ .sg-rating-number{opacity:1;position:absolute;bottom:-15px;font:8px Consolas}$ .sg-rating-core{opacity:1;transition:transform .5s,background .4s,box-shadow .4s}'
 for id,desc,css in [
 ('domino-rating','小さなドミノの目と番号を、触れやすい五つの評価面にする。','${--sg-a:#c9d8b6;--sg-line:#8eaa77}$ .sg-rating-field{background:#2b442d;border-radius:4px;padding:22px 17px}$ .sg-rating-core{inset:2px 4px 0;border-radius:3px;background:radial-gradient(circle at 50% 28%,#a6be8b 0 2px,transparent 3px),radial-gradient(circle at 50% 70%,#a6be8b 0 2px,transparent 3px),#4b6940;border:1px solid #8fa879;box-shadow:0 3px 0 #1c2b2177}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:radial-gradient(circle at 50% 28%,#355331 0 2px,transparent 3px),radial-gradient(circle at 50% 70%,#355331 0 2px,transparent 3px),#becfa3;transform:translateY(-3px)}'),
 ('leaflet-rating','二枚の葉のような評価面が、選択時に軽く開く。','${--sg-a:#b2d2bb;--sg-line:#779e86}$ .sg-rating-core{inset:6px 9px;background:#456e54;border:1px solid #7ea387;border-radius:85% 10% 85% 10%;transform:rotate(-18deg)}$ .sg-rating-core:after{content:"";position:absolute;inset:3px 1px;border-left:1px solid #bed8a8;border-radius:50%;transform:rotate(28deg)}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(130deg,#d1dfb0,#779e77);transform:rotate(12deg);box-shadow:0 5px 7px #163a2777}$ .sg-rating-scale{gap:18px;border-bottom:1px solid #78a48955;padding-bottom:10px}'),
 ('chime-rating','長さの違う細い鈴を並べ、評価の高さを選んだ鈴で読む。','${--sg-a:#b7d1df;--sg-line:#7d9db2}$ .sg-rating-scale{border-top:1px solid #8caec0;padding-top:12px}$ .sg-rating-form{align-items:start}$ .sg-rating-core{inset:0 12px auto;height:calc(22px + var(--rank)*4px);border:1px solid #a9c3cd;border-radius:1px 1px 35% 35%;background:linear-gradient(90deg,#5d839a,#96b1bd,#476a80);box-shadow:0 3px 5px #00182755}$ .sg-rating-core:before{content:"";position:absolute;width:1px;height:13px;left:50%;top:-14px;background:#8caec0}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(90deg,#9cc4ce,#d1e7e2,#739baa);transform:rotate(-3deg)}'),
 ('pinned-award-rating','四角い評価章と細い足を組み合わせ、選んだ章を明るく留める。','${--sg-a:#dec1a3;--sg-line:#aa8f72}$ .sg-rating-core{inset:3px 5px 7px;background:linear-gradient(135deg,#826549,#b39570);border:2px solid #c6a87c;border-radius:2px;transform:rotate(-6deg)}$ .sg-rating-core:after{content:"";position:absolute;width:13px;height:15px;background:#816747;left:calc(50% - 6px);bottom:-14px;clip-path:polygon(0 0,100% 0,100% 100%,50% 75%,0 100%)}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(135deg,#ead2a7,#ac8c5e);transform:rotate(0);border-color:#eddbb7}'),
 ('wedge-scale-rating','傾きの違う小さな楔が、選択された段まで明るくつながる。','${--sg-a:#c0bddf;--sg-line:#8b83ae}$ .sg-rating-core{inset:6px 2px 0;border:0;background:linear-gradient(130deg,#7d72a7,#403565);clip-path:polygon(0 22%,100% 0,100% 78%,0 100%);box-shadow:none}$ .sg-rating-scale{gap:9px}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(130deg,#d1c2e8,#8d7dad);transform:translateY(-4px)}$ .sg-rating-tick{width:20px;height:1px;left:calc(50% - 10px);border-radius:0}'),
 ('seedpod-rating','細い種の房を、軽い五段階の評価として並べる。','${--sg-a:#cbd4a8;--sg-line:#91a173}$ .sg-rating-core{inset:2px 10px;background:linear-gradient(90deg,#5e714a,#9cb173,#526944);border:1px solid #b1c38f;border-radius:50%;box-shadow:inset 0 1px #d8e5b733}$ .sg-rating-core:after{content:"";position:absolute;top:4px;bottom:4px;left:50%;border-left:1px solid #ccd8a288;border-radius:50%}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(90deg,#96ad6d,#d7dfa8,#8fa46c);transform:scale(1.1)}$ .sg-rating-scale{gap:17px}'),
 ('keycap-rating','五つの低いキーを押し込み、選んだ評価を手元の操作として示す。','${--sg-a:#b4cbd9;--sg-line:#7e9bac}$ .sg-rating-core{inset:3px 2px 2px;background:linear-gradient(#7a96a8,#3a5d75);border:1px solid #a1bac6;border-radius:5px;box-shadow:0 5px 0 #173449,inset 0 1px #d7e5de55}$ .sg-rating-number{bottom:14px;color:#deeee8;font:12px Consolas;z-index:1}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(#afc9d2,#7d9cae);transform:translateY(4px);box-shadow:0 1px 0 #173449,inset 0 1px #e5f0e355}$ .sg-rating-tick{display:none}$ .sg-rating-scale{gap:8px}'),
 ('perforated-score-rating','一枚ずつ区切った小さな評価札を、選んだ段まで濃く残す。','${--sg-a:#b5849c;--sg-ink:#493342;--sg-muted:#927486;--sg-line:#aa8b9f}$ .sg-rating-field{background:#e6d2df;border-radius:0;border-top:6px solid #b698b2}$ .sg-rating-core{inset:0 2px 1px;background:#c4a6be;border-left:2px dotted #9c7897;border-radius:0;box-shadow:2px 2px #a6869e44}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:#9f789b;border-left-color:#6e4e70}$ .sg-rating-number{color:#453047}$ .sg-rating-info{border-color:#a27d9c}$ .sg-rating-unit[data-filled=true] .sg-rating-tick{background:#634963}'),
 ('crescent-score-rating','開いた月の形が、評価の段を軽やかに重ねる。','${--sg-a:#cbb9dc;--sg-line:#9279a6}$ .sg-rating-core{inset:4px;background:linear-gradient(130deg,#8e77a7,#4a3b69);border-radius:50%;clip-path:polygon(0 0,100% 0,67% 23%,53% 50%,69% 78%,100% 100%,0 100%);border:1px solid #b398c9;transform:rotate(-15deg)}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:linear-gradient(130deg,#e3c8ed,#a08dbd);transform:rotate(0)}$ .sg-rating-scale{gap:20px}$ .sg-rating-number{font-family:Georgia}'),
 ('crossbar-score-rating','小さな横桟を選び、幅広い番号の上で評価を固定する。','${--sg-a:#b4d2c4;--sg-line:#7ca491}$ .sg-rating-core{inset:15px 1px 10px;background:#4c795f;border-radius:1px;border:1px solid #a1c8a9;box-shadow:0 3px 0 #15382b77}$ .sg-rating-core:after{content:"";position:absolute;width:3px;height:29px;left:calc(50% - 1px);top:-10px;background:#8aaa85;z-index:-1}$ .sg-rating-number{bottom:-17px;font:11px Georgia;letter-spacing:1px}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:#bbd3a8;transform:translateY(-5px)}$ .sg-rating-info{margin-top:27px}'),
 ('plume-score-rating','細い羽根の軸と枝が、選択した段まで順に立ち上がる。','${--sg-a:#dbbaa8;--sg-line:#ac8d77}$ .sg-rating-core{inset:0 15px 0;background:#b19775;border-radius:2px;transform:rotate(-8deg)}$ .sg-rating-petals i{display:block;position:absolute;left:50%;top:calc(var(--petal)*5px);width:15px;height:4px;background:#775d49;transform:rotate(-30deg);border-radius:80% 10% 50% 0;transform-origin:left center;transition:transform .5s,background .5s}$ .sg-rating-unit[data-filled=true] .sg-rating-petals i{background:#d7b484;transform:rotate(-15deg) scaleX(1.12)}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:#e3c49b;transform:rotate(3deg)}$ .sg-rating-scale{gap:18px}'),
 ('segmented-seal-rating','区切りのある四角い印が、評価の値をひとつずつ押し留める。','${--sg-a:#bfd0d7;--sg-line:#82a0ab}$ .sg-rating-core{inset:5px 3px;background:#426974;border:3px double #a5c5c8;border-radius:1px;box-shadow:3px 3px #173e4b77;transform:skewY(-6deg)}$ .sg-rating-number{bottom:13px;z-index:2;color:#dce9df;font:12px Georgia}$ .sg-rating-unit[data-filled=true] .sg-rating-core{background:#9fc3c2;color:#214b53;transform:skewY(0) translateY(3px);box-shadow:1px 1px #173e4b77}$ .sg-rating-unit[data-filled=true] .sg-rating-number{color:#173c47}$ .sg-rating-tick{display:none}'),
 ]:p('ratings',id,desc,ratingbase+css)
